from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

ROOT = Path('/home/ubuntu/ws4_encounter_bible')


def outcome(terminal: bool, state: str | None, changes: list[str], summary: str) -> dict[str, Any]:
    data: dict[str, Any] = {
        'terminal': terminal,
        'stateChanges': changes,
        'summary': summary,
    }
    if state is not None:
        data['terminalState'] = state
    return data


def receipt(kind: str, target: str, operation: str, value: Any) -> dict[str, Any]:
    return {'type': kind, 'target': target, 'operation': operation, 'value': value}


def cue(channel: str, signal: str, inference: str, action_hook: str) -> dict[str, str]:
    return {
        'channel': channel,
        'signal': signal,
        'inference': inference,
        'actionHook': action_hook,
    }


def governance(template: dict[str, Any]) -> dict[str, Any]:
    clone = json.loads(json.dumps(template, sort_keys=True))
    clone.pop('governance', None)
    digest = hashlib.sha256(json.dumps(clone, sort_keys=True).encode()).hexdigest()[:16]
    return {
        'stage': 'draft',
        'contentHash': digest,
        'owner': 'encounter-design',
        'replaces': None,
    }


def litrpg_template(spec: dict[str, Any]) -> dict[str, Any]:
    fight_id = spec.get('fight_id', 'fight')
    flee_id = spec.get('flee_id', 'flee')
    parley_id = spec.get('parley_id', 'negotiate')
    fight_success = outcome(
        True,
        'victory',
        [f"enemy:{spec['enemy_id']}:defeated", f"objective:{spec['objective_id']}:complete"],
        spec['victory_summary'],
    )
    fight_failure = outcome(
        False,
        None,
        ['player:hp:decrement_resolved_damage', 'encounter:danger:increment:1'],
        'The enemy lands a resolved hit and danger rises; the encounter state cannot remain unchanged.',
    )
    flee_success = outcome(
        True,
        'fled',
        [f"location:set:{spec['flee_destination']}", 'resource:stamina:decrement:flee_cost', 'encounter:set:fled'],
        spec['flee_summary'],
    )
    flee_failure = outcome(
        False,
        None,
        ['encounter:escape_route:lock_current', 'encounter:danger:increment:2', 'resource:stamina:decrement:1'],
        'The current route closes, danger advances, and a different route or tactic is required.',
    )
    parley_success = outcome(
        True,
        'negotiated',
        [f"resource:{spec['leverage']}:remove:1", f"enemy:{spec['enemy_id']}:state:{spec['parley_state']}", 'encounter:set:negotiated'],
        spec['parley_summary'],
    )
    parley_failure = outcome(
        False,
        None,
        [f"resource:{spec['leverage']}:set:discredited", 'encounter:danger:increment:2', 'approach:negotiate:lock'],
        'The offer is rejected and discredited; the same concession cannot be repeated.',
    )
    approaches = [
        {
            'id': fight_id,
            'label': spec['fight_label'],
            'requirements': ['player:combat_capable'],
            'method': 'combat',
            'check': {'clock': {'successSegments': spec['success_segments'], 'dangerSegments': spec['danger_segments']}},
            'onSuccess': fight_success,
            'onPartial': outcome(False, None, [f"enemy:{spec['enemy_id']}:hp:decrement", 'player:resource:decrement:resolved_cost'], 'Damage is committed while a separate cost is paid.'),
            'onFailure': fight_failure,
            'lockout': 'Each combat action changes HP, resources, position, or danger before it can be offered again.',
        },
        {
            'id': flee_id,
            'label': spec['flee_label'],
            'requirements': [f"route:{spec['flee_destination']}:available"],
            'method': 'clock',
            'check': {'clock': {'successSegments': 4, 'dangerSegments': 4}},
            'onSuccess': flee_success,
            'onPartial': outcome(True, 'fled', [f"location:set:{spec['flee_destination']}", 'player:condition:add:winded', 'loot:carried_unbound:remove:1'], 'Escape succeeds with a visible injury or lost carried item.'),
            'onFailure': flee_failure,
            'lockout': 'Failure locks the current route and modifies the next flee option.',
        },
        {
            'id': parley_id,
            'label': spec['parley_label'],
            'requirements': [f"resource:{spec['leverage']}:available", spec['parley_threshold']],
            'method': 'deterministic',
            'onSuccess': parley_success,
            'onFailure': parley_failure,
            'lockout': 'The leverage is consumed on success or discredited on refusal.',
        },
    ]
    data = {
        'schemaVersion': '1.0.0',
        'templateVersion': '1.0.0',
        'id': spec['id'],
        'mode': 'litrpg',
        'bibleId': 'summoned-pact',
        'name': spec['name'],
        'role': spec['role'],
        'summary': spec['summary'],
        'telegraph': {
            'required': not spec.get('surprise', False),
            'channels': [item['channel'] for item in spec['cues']],
            'cues': spec['cues'],
            'responseWindowTurns': spec.get('response_turns', 2),
            'surpriseEligible': spec.get('surprise', False),
            'openingSeverityCap': 'moderate' if spec.get('surprise', False) else 'none',
        },
        'stakes': {'headline': spec['stakes'], 'approaches': approaches},
        'resolution': {
            'mechanic': 'combat',
            'config': {
                'tierBand': spec['tier'],
                'enemyHp': spec['enemy_hp'],
                'damageRule': 'max(1, attack + skill + seededVariance - defense)',
                'fleeRule': 'opposed success/danger clocks; route locks after failed attempt',
                'parleyRule': 'requires named leverage and threshold; consume or discredit once',
            },
            'terminalStates': ['victory', 'defeat', 'fled', 'negotiated', 'partial'],
            'maxTurns': spec['max_turns'],
            'forcedTerminal': outcome(True, spec['forced_state'], spec['forced_changes'], spec['forced_summary']),
            'antiRepeatRule': 'Every action mutates HP, a clock, a resource, position, legality, or terminal state.',
        },
        'aftermath': {
            'minimumReceiptTypes': spec['receipt_min'],
            'byTerminal': {
                'victory': [
                    receipt('xp', 'player.progression', 'add', spec['xp']),
                    receipt('loot', spec['loot_table'], 'unlock', spec['loot_preview']),
                    receipt('dungeon', spec['objective_id'], 'set', 'cleared'),
                ],
                'fled': [
                    receipt('dungeon', spec['objective_id'], 'set', 'unresolved_cooldown'),
                    receipt('quest', spec['followup'], 'unlock', True),
                ],
                'negotiated': [
                    receipt('faction', spec['faction'], 'increment', spec['faction_delta']),
                    receipt('npc', spec['enemy_id'], 'set', spec['parley_state']),
                    receipt('quest', spec['followup'], 'unlock', True),
                ],
                'defeat': [
                    receipt('npc', 'player', 'set', spec['defeat_condition']),
                    receipt('quest', spec['fail_forward'], 'unlock', True),
                ],
            },
        },
        'biomeFilter': {
            'allow': spec['biomes'],
            'siteTags': spec['site_tags'],
            'requireFactionTags': spec['faction_tags'],
            'exclude': spec['exclude'],
        },
        'turnWindow': {
            'earliest': spec['earliest'],
            'latest': spec['latest'],
            'cooldown': spec['cooldown'],
            'droughtEligible': spec['drought'],
        },
        'governance': {},
        'example': {
            'telegraphProse': spec['telegraph_prose'],
            'stakesProse': spec['stakes_prose'],
            'resolutionProse': spec['resolution_prose'],
            'receiptProse': spec['receipt_prose'],
        },
    }
    data['governance'] = governance(data)
    return data


