def pyoa_template(spec: dict[str, Any]) -> dict[str, Any]:
    approaches = []
    terminal_map: dict[str, list[dict[str, Any]]] = {}
    for option in spec['options']:
        approaches.append({
            'id': option['id'],
            'label': option['label'],
            'requirements': option.get('requirements', []),
            'method': 'fork',
            'onSuccess': outcome(True, 'crisisEnding', [
                f"fact:{option['set_fact']}:set:true",
                f"fact:{option['lock_fact']}:lock:false",
                f"callback:{option['callback']}:schedule",
                f"ending:{option['ending']}:eligible",
                f"convergence:{spec['convergence']}:preserve_flags",
            ] + option.get('extra_changes', []), option['summary']),
            'onFailure': outcome(False, None, ['choice:validation_error:record', 'choice:remain_uncommitted'], 'The engine rejects an illegal option without consuming a turn.'),
            'lockout': 'A valid fork commits once; the opposing fact is locked until an explicitly authored reversal crisis.',
        })
        terminal_map[option['id']] = [
            receipt('quest', option['callback'], 'unlock', True),
            receipt('faction', option['faction'], 'increment', option['faction_delta']),
            receipt('npc', option['npc'], 'set', option['npc_state']),
        ]
    data = {
        'schemaVersion': '1.0.0',
        'templateVersion': '1.0.0',
        'id': spec['id'],
        'mode': 'pyoa',
        'bibleId': spec['bible'],
        'name': spec['name'],
        'role': 'crisis',
        'summary': spec['summary'],
        'telegraph': {
            'required': True,
            'channels': [c['channel'] for c in spec['cues']],
            'cues': spec['cues'],
            'responseWindowTurns': spec['response_turns'],
            'surpriseEligible': False,
            'openingSeverityCap': 'none',
        },
        'stakes': {'headline': spec['stakes'], 'approaches': approaches},
        'resolution': {
            'mechanic': 'fork',
            'config': {
                'exclusiveFactGroup': spec['fact_group'],
                'delayedPayoffAt': spec['payoff_at'],
                'convergencePoint': spec['convergence'],
                'convergencePolicy': 'merge scene topology only; preserve facts, callbacks, relationships, and ending eligibility',
                'commitOnce': True,
            },
            'terminalStates': ['crisisEnding'],
            'maxTurns': spec['max_turns'],
            'forcedTerminal': outcome(True, 'crisisEnding', [
                f"fact:{spec['timeout_fact']}:set:true",
                f"callback:{spec['timeout_callback']}:schedule",
                f"ending:{spec['timeout_ending']}:eligible",
                f"convergence:{spec['convergence']}:preserve_flags",
            ], spec['timeout_summary']),
            'antiRepeatRule': 'After commit, the crisis ID is terminal and cannot respawn; convergence reads stored flags.',
        },
        'aftermath': {'minimumReceiptTypes': 3, 'byTerminal': terminal_map},
        'biomeFilter': {
            'allow': spec['biomes'],
            'siteTags': spec['site_tags'],
            'requireFactionTags': spec['faction_tags'],
            'exclude': spec['exclude'],
        },
        'turnWindow': {
            'earliest': spec['earliest'],
            'latest': spec['latest'],
            'cooldown': 9999,
            'droughtEligible': spec['drought'],
        },
        'governance': {},
        'example': {
            'telegraphProse': spec['telegraph_prose'],
            'stakesProse': spec['stakes_prose'],
            'resolutionProse': spec['resolution_prose'],
            'receiptProse': spec['receipt_prose'],
        },
    }
    data['governance'] = governance(data)
    return data


