def pyoa_option(option_id: str, label: str, set_fact: str, lock_fact: str, callback: str, ending: str,
                 faction: str, faction_delta: int, npc: str, npc_state: str, summary: str,
                 requirements: list[str] | None = None, extra_changes: list[str] | None = None) -> dict[str, Any]:
    return {
        'id': option_id, 'label': label, 'set_fact': set_fact, 'lock_fact': lock_fact,
        'callback': callback, 'ending': ending, 'faction': faction, 'faction_delta': faction_delta,
        'npc': npc, 'npc_state': npc_state, 'summary': summary,
        'requirements': requirements or [], 'extra_changes': extra_changes or [],
    }


