def make_pyoa_spec(
    bible: str,
    slug: str,
    name: str,
    summary: str,
    signal: str,
    stakes: str,
    option_a: tuple[str, str, str, str, str, str, str, int, str, str],
    option_b: tuple[str, str, str, str, str, str, str, int, str, str],
    payoff_at: str,
    convergence: str,
    timeout_fact: str,
    timeout_callback: str,
    timeout_ending: str,
    biomes: list[str],
    site_tags: list[str],
    faction_tags: list[str],
    earliest: int,
    latest: int,
) -> dict[str, Any]:
    a_id, a_label, a_fact, a_lock, a_callback, a_ending, a_faction, a_delta, a_npc, a_state = option_a
    b_id, b_label, b_fact, b_lock, b_callback, b_ending, b_faction, b_delta, b_npc, b_state = option_b
    return {
        'id': f'{bible}.crisis.{slug}',
        'bible': bible,
        'name': name,
        'summary': summary,
        'cues': [cue('scene', signal, 'The crisis presents an exclusive decision with a visible future callback.', a_id)],
        'response_turns': 2,
        'stakes': stakes,
        'fact_group': f'{slug}-commitment',
        'payoff_at': payoff_at,
        'convergence': convergence,
        'max_turns': 3,
        'timeout_fact': timeout_fact,
        'timeout_callback': timeout_callback,
        'timeout_ending': timeout_ending,
        'timeout_summary': f'Delay commits {timeout_fact}; the crisis ends and schedules {timeout_callback}.',
        'options': [
            pyoa_option(a_id, a_label, a_fact, a_lock, a_callback, a_ending, a_faction, a_delta, a_npc, a_state, f'{a_label} writes a durable fact and qualifies {a_ending}.'),
            pyoa_option(b_id, b_label, b_fact, b_lock, b_callback, b_ending, b_faction, b_delta, b_npc, b_state, f'{b_label} writes the opposing fact and qualifies {b_ending}.'),
        ],
        'biomes': biomes,
        'site_tags': site_tags,
        'faction_tags': faction_tags,
        'exclude': [item for item in ['thornferry', 'vesper-glass', 'erebus-9', 'ashwinter-court'] if item != bible],
        'earliest': earliest,
        'latest': latest,
        'drought': True,
        'telegraph_prose': signal,
        'stakes_prose': f'{a_label} or {b_label}; each writes an exclusive fact, a delayed callback, and distinct ending eligibility.',
        'resolution_prose': f'The choice commits once within three turns. Both paths converge at {convergence}, which reads rather than erases the stored flags.',
        'receipt_prose': f'The receipt records the selected fact, the locked opposite, faction and NPC changes, callback {payoff_at}, and ending eligibility.',
    }


