def write_json(name: str, payload: dict[str, Any]) -> None:
    (ROOT / name).write_text(json.dumps(payload, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')


def lifecycle_summary(template: dict[str, Any]) -> str:
    cues = '<br>'.join(f"**{c['channel'].upper()}:** {c['signal']}" for c in template['telegraph']['cues'])
    approaches = '<br>'.join(f"**{a['label']}** — {a['onSuccess']['summary']}" for a in template['stakes']['approaches'])
    forced = template['resolution']['forcedTerminal']['summary']
    receipt_types = sorted({r['type'] for rows in template['aftermath']['byTerminal'].values() for r in rows})
    biome = ', '.join(template['biomeFilter']['allow'])
    return (
        f"| Telegraph | {cues} |\n"
        f"| Stakes | {template['stakes']['headline']}<br>{approaches} |\n"
        f"| Resolution | `{template['resolution']['mechanic']}`; maximum {template['resolution']['maxTurns']} turns. **Forced terminal:** {forced} |\n"
        f"| Aftermath | Minimum {template['aftermath']['minimumReceiptTypes']} receipt types; supported: {', '.join(receipt_types)}. |\n"
        f"| Biome and window | {biome}; eligible turns {template['turnWindow']['earliest']}–{template['turnWindow']['latest']}; cooldown {template['turnWindow']['cooldown']}. |\n"
    )


def write_markdown(name: str, title: str, intro: str, templates: list[dict[str, Any]]) -> None:
    lines = [f'# {title}', '', intro, '', '## Library Index', '', '| ID | Template | Role | Max turns | Telegraph channels |', '| --- | --- | --- | ---: | --- |']
    for t in templates:
        lines.append(f"| `{t['id']}` | {t['name']} | {t['role']} | {t['resolution']['maxTurns']} | {', '.join(t['telegraph']['channels'])} |")
    for index, t in enumerate(templates, 1):
        lines.extend([
            '', f"## {index}. {t['name']}", '', t['summary'], '', '| Lifecycle phase | Contract |', '| --- | --- |', lifecycle_summary(t),
            '', '**Prose example.**', '',
            f"> **Telegraph:** {t['example']['telegraphProse']}", '>',
            f"> **Stakes:** {t['example']['stakesProse']}", '>',
            f"> **Resolution:** {t['example']['resolutionProse']}", '>',
            f"> **Aftermath:** {t['example']['receiptProse']}",
        ])
    (ROOT / name).write_text('\n'.join(lines) + '\n', encoding='utf-8')


def main() -> None:
    litrpg = [litrpg_template(spec) for spec in LITRPG_SPECS]
    dnd = [dnd_template(spec) for spec in DND_SPECS]
    rpg = [rpg_template(spec) for spec in RPG_SPECS]
    pyoa = [pyoa_template(spec) for spec in PYOA_SPECS]

    write_json('D2_litrpg_encounter_library.json', {'schemaVersion': '1.0.0', 'libraryId': 'ws4.litrpg.summoned-pact', 'mode': 'litrpg', 'bibleId': 'summoned-pact', 'templates': litrpg})
    write_json('D3_dnd_encounter_library.json', {'schemaVersion': '1.0.0', 'libraryId': 'ws4.dnd.cursed-keep', 'mode': 'dnd', 'bibleId': 'cursed-keep', 'templates': dnd})
    write_json('D4_rpg_encounter_library.json', {'schemaVersion': '1.0.0', 'libraryId': 'ws4.rpg.cape-district', 'mode': 'rpg', 'bibleId': 'cape-district', 'templates': rpg})
    write_json('D5_pyoa_crisis_library.json', {'schemaVersion': '1.0.0', 'libraryId': 'ws4.pyoa.crises', 'mode': 'pyoa', 'bibles': sorted({t['bibleId'] for t in pyoa}), 'templates': pyoa})

    write_markdown('D2_litrpg_encounter_library.md', 'D2 — LitRPG Encounter Library', 'Eight **Summoned Pact** templates use visible tier/HP rules, real flee and parley terminals, deterministic ledger updates, typed loot, and bounded turn windows.', litrpg)
    write_markdown('D3_dnd_encounter_library.md', 'D3 — DnD Encounter Library', 'Eight **Cursed Keep** templates cover combat, traps, checks, hazards, duels, puzzles, a boss, and a random event. Each declares the d20 ability/skill, DC, modifier source, advantage/disadvantage conditions, and consequences.', dnd)
    write_markdown('D4_rpg_encounter_library.md', 'D4 — RPG Encounter Library', 'Eight **Cape District** templates resolve social and political pressure through named leverage, progress/danger clocks, irreversible concessions, and terminal withdrawal.', rpg)
    write_markdown('D5_pyoa_crisis_library.md', 'D5 — PYOA Crisis Library', 'Four PYOA bibles contain six crises each. Every fork writes an exclusive fact, locks the opposing fact, schedules a delayed callback, changes ending eligibility, and converges without deleting branch state.', pyoa)


if __name__ == '__main__':
    main()

